sudo -n env SST_PASSWORD=[REDACTED] APP_PASSWORD=[REDACTED] sh -c 'mysql --defaults-file=/etc/mysql/debian.cnf --protocol=socket <<SQL
DROP USER IF EXISTS \"\"@\"localhost\";
DROP USER IF EXISTS \"\"@\"%\";
DROP USER IF EXISTS \"root\"@\"%\";
DROP USER IF EXISTS \"root\"@\"127.0.0.1\";
DROP USER IF EXISTS \"root\"@\"::1\";
DROP DATABASE IF EXISTS test;
CREATE DATABASE IF NOT EXISTS galera_app CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
GRANT RELOAD, LOCK TABLES, PROCESS, REPLICATION CLIENT ON *.* TO \"sstuser\"@\"localhost\" IDENTIFIED BY [REDACTED]
GRANT ALL PRIVILEGES ON galera_app.* TO \"galera_app\"@\"10.100.201.%\" IDENTIFIED BY [REDACTED]
FLUSH PRIVILEGES;
SQL'

